import math
import itertools

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def solve_search():
    min_f = float('inf')
    found_pairs = []

    # Iterate over c <= d since f(c, d) is symmetric
    for c in range(1, 25):
        for d in range(c, 25):
            if c + d >= 25:
                continue

            if gcd(c, d) != 1:
                continue

            # 2. Check the discriminant D
            D = c**2 - 6*c*d + d**2

            # 3. Check if D is a perfect square m^2
            if is_perfect_square(D):
                # 4. Calculate f(c, d) = c/d + d/c
                f_cd = c/d + d/c

                # Record findings
                found_pairs.append({
                    'c': c, 
                    'd': d, 
                    'D': D, 
                    'm': int(math.sqrt(D)),
                    'f': f_cd
                })

                # 5. Update minimum value
                if f_cd < min_f:
                    min_f = f_cd

    print(f"Found pairs: {found_pairs}")
    if found_pairs:
        print(f"Minimum f(c, d) found: {min_f}")
    else:
        print("No pairs found satisfying the condition.")

solve_search()
